-- folder.edit (line 21): owner or parent.edit
CREATE OR REPLACE VIEW authz_int."folder__edit" AS
  SELECT c.descendant AS id FROM authz_int."folder__parent__tree" c
  WHERE c.ancestor IN (SELECT s.id FROM authz_int."folder__edit__start"() s(id));

-- folder.edit for one object (checks of single rows and authz.can)
CREATE OR REPLACE FUNCTION authz_int."folder__edit__has"(p_id integer) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" c
    WHERE c.descendant = $1
      AND EXISTS (SELECT 1 FROM (
  SELECT id FROM authz_int."folder__owner") s WHERE s.id = c.ancestor));
END $f$;

-- folder.view (line 22): edit or team or viewer or parent.view
CREATE OR REPLACE VIEW authz_int."folder__view" AS
  SELECT c.descendant AS id FROM authz_int."folder__parent__tree" c
  WHERE c.ancestor IN (SELECT s.id FROM authz_int."folder__view__start"() s(id));

-- folder.view for one object (checks of single rows and authz.can)
CREATE OR REPLACE FUNCTION authz_int."folder__view__has"(p_id integer) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN EXISTS (SELECT 1 FROM authz_int."folder__parent__tree" c
    WHERE c.descendant = $1
      AND EXISTS (SELECT 1 FROM (
  (SELECT id FROM authz_int."folder__owner")
  UNION ALL
  (SELECT id FROM authz_int."folder__team")
  UNION ALL
  (SELECT id FROM authz_int."folder__viewer")) s WHERE s.id = c.ancestor));
END $f$;

-- app.folders: no row has the id, or the user may select it (what the rules' explanations answer for)
CREATE OR REPLACE FUNCTION authz_int."app.folders:seen"(p_id integer) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN NOT EXISTS (SELECT 1 FROM "app"."folders" o WHERE o."id" = $1)
      OR EXISTS (SELECT 1 FROM "app"."folders" "folders" WHERE "folders"."id" = $1
        AND (SELECT authz_int.scope_cmd('app.folders', 'select')) AND (coalesce("folders"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = "folders"."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = "folders"."id")
    OR authz_int."folder__view__has"("folders"."parent_id")));
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.folders:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."folders"; r_new "app"."folders";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY['no   there is no insert rule for app.folders: nobody may insert its rows'];
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.folders', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "app"."folders" x WHERE x."id" = $2::integer;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for app.folders: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."app.folders:update:why"(r_old, true)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."app.folders:update:why"(r_new, false) l) END;
END $f$;

-- app.files: no row has the id, or the user may select it (what the rules' explanations answer for)
CREATE OR REPLACE FUNCTION authz_int."app.files:seen"(p_id integer) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN NOT EXISTS (SELECT 1 FROM "app"."files" o WHERE o."id" = $1)
      OR EXISTS (SELECT 1 FROM "app"."files" "files" WHERE "files"."id" = $1
        AND (SELECT authz_int.scope_cmd('app.files', 'select')) AND (coalesce("files"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = "files"."id")
    OR authz_int."folder__edit__has"("files"."folder_id")
    OR (NOT coalesce((confidential), false)
    AND authz_int."folder__view__has"("files"."folder_id"))));
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.files:insert:why"(p_row "app"."files") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.files:insert:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : folder.edit and owner  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.files insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not insert on app.files'
    ELSE '  no   the sign-in''s scopes do not allow insert on app.files' END; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'folder.edit';
  IF NOT v[4] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("files"."folder_id")::text AS id FROM (SELECT ($1).*) AS "files") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('folder', v_t.id, 'edit') l LIMIT 20;
    END LOOP;
  END IF;
  RETURN NEXT CASE WHEN v[5] THEN '  yes  ' ELSE '  no   ' END || 'owner';
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.files:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."files"; r_new "app"."files";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."app.files:insert:why"(jsonb_populate_record(NULL::"app"."files", coalesce($3, '{}'))));
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.files', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "app"."files" x WHERE x."id" = $2::integer;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for app.files: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."app.files:update:why"(r_old, true)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."app.files:update:why"(r_new, false) l) END;
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.notes:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."notes"; r_new "app"."notes";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY['no   there is no insert rule for app.notes: nobody may insert its rows'];
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.notes', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT (jsonb_populate_record(NULL::"app"."notes", to_jsonb(x.*))).* INTO r_old FROM "app"."notes_visible" x WHERE x."id" = $2::integer;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY['no   there is no delete rule for app.notes: nobody may delete its rows'];
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY['no   there is no update rule for app.notes: nobody may update its rows'];
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."app.folders:column parent_id after:why"(p_row "app"."folders") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.folders:column parent_id after:items"(p_row, current_user); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update parent_id after : parent.edit  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.folders update parent_id after'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT CASE WHEN coalesce(pg_catalog.current_setting('authz.acting_user', true), '') <> ''
    THEN '  no   the session views as someone else: it may not update on app.folders'
    ELSE '  no   the sign-in''s scopes do not allow update on app.folders' END; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'parent.edit';
  IF NOT v[4] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("folders"."parent_id")::text AS id FROM (SELECT ($1).*) AS "folders") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '    ' || l FROM authz.explain('folder', v_t.id, 'edit') l LIMIT 20;
    END LOOP;
  END IF;
END $f$;

-- On a partitioned table, an update that puts a row in another partition is a delete there and an insert here:
-- Postgres runs no AFTER UPDATE row trigger for it. Where the rule's trigger runs after the update, the rule is
-- asked again when the statement is done, of each row it left with other values in these columns than the row that
-- had its key (a key the update made: than the one key it left without a row, or, where that isn't one for one,
-- whatever changed). A trigger before the update has asked it of every row already
CREATE OR REPLACE FUNCTION authz_int."app.folders:column parent_id after:moved"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
<<authz__>>
DECLARE v_lines text; v_row "app"."folders"; v_one boolean; v_virtual text;
BEGIN
  IF NOT pg_catalog.row_security_active('"app"."folders"'::pg_catalog.regclass) THEN RETURN NULL; END IF;
  -- (tgtype's bit 2: before. Asked unless a trigger before the update is there, and on: without one, never less)
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_trigger g WHERE g.tgrelid = '"app"."folders"'::pg_catalog.regclass AND g.tgname = 'authz_update_after parent_id'
             AND g.tgtype & 2 <> 0 AND g.tgenabled <> 'D') THEN
    RETURN NULL;
  END IF;
  -- (PostgreSQL 18: each row with its virtual generated columns, which the statement's rows don't hold)
  SELECT pg_catalog.string_agg(pg_catalog.format('%L, (%s)', a.attname, pg_catalog.pg_get_expr(d.adbin, d.adrelid)), ', ')
      INTO v_virtual FROM pg_catalog.pg_attribute a
      JOIN pg_catalog.pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
      WHERE a.attrelid = '"app"."folders"'::pg_catalog.regclass AND a.attnum > 0 AND NOT a.attisdropped AND a.attgenerated = 'v';
  v_one := (SELECT count(*) FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)) = 1
       AND (SELECT count(*) FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)) = 1;
  FOR v_row IN
    SELECT (pg_catalog.jsonb_populate_record(NULL::"app"."folders", pg_catalog.to_jsonb(n.*))).* FROM new_rows n
    WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text AND o."parent_id" IS NOT DISTINCT FROM n."parent_id")
      AND NOT (authz__.v_one AND NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
               AND EXISTS (SELECT 1 FROM old_rows o WHERE o."parent_id" IS NOT DISTINCT FROM n."parent_id"
                           AND NOT EXISTS (SELECT 1 FROM new_rows m WHERE m."id"::text = o."id"::text)))
  LOOP
    IF v_virtual IS NOT NULL THEN
      EXECUTE 'SELECT (pg_catalog.jsonb_populate_record($1, pg_catalog.jsonb_build_object(' || v_virtual
        || '))).* FROM (SELECT ($1).*) AS r' INTO v_row USING v_row;
    END IF;
    IF NOT (authz_gen."app.folders:column parent_id after:items"(v_row, current_user))[1] THEN
      BEGIN
        v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."app.folders:column parent_id after:why"(v_row) l);
      EXCEPTION WHEN OTHERS THEN
        v_lines := 'no explanation: ' || SQLERRM;
      END;
      RAISE EXCEPTION 'changing parent_id of app.folders % needs: parent.edit', v_row."id" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
        SCHEMA = 'app', TABLE = 'folders', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
    END IF;
  END LOOP;
  RETURN NULL;
END $f$;

-- What the app role evaluates itself (its rules, the views they read, the rules' own functions, the masked views)
-- calls nothing of the app's that may read data: a call the condition's text doesn't show isn't run as the owner
DO $ac$
DECLARE r record;
BEGIN
  FOR r IN
    WITH RECURSIVE read(classid, objid, what) AS (
      SELECT x.classid, x.objid, x.what FROM (
        SELECT 'pg_policy'::regclass::oid AS classid, p.oid AS objid,
               format('the %s rule of %s', substr(p.polname::text, 7), p.polrelid::regclass) AS what
        FROM pg_policy p JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
         AND d.description IN ('rowstile')
        UNION ALL
        SELECT 'pg_proc'::regclass::oid, f.oid, 'the rules of ' || split_part(f.proname::text, ':', 1)
        FROM pg_proc f WHERE f.pronamespace = 'authz_gen'::regnamespace
        UNION ALL
        SELECT 'pg_rewrite'::regclass::oid, w.oid, 'the masked view ' || c.oid::regclass
        FROM pg_class c JOIN pg_description d ON d.objoid = c.oid AND d.classoid = 'pg_class'::regclass
         AND d.description IN ('rowstile masked view')
        JOIN pg_rewrite w ON w.ev_class = c.oid) x
      UNION
      -- (the views they read, and those these read: a view runs what it calls as whoever reads it)
      SELECT 'pg_rewrite'::regclass::oid, w.oid, rd.what
      FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
       AND dep.refclassid = 'pg_class'::regclass
      JOIN pg_class v ON v.oid = dep.refobjid AND v.relkind = 'v' AND v.relnamespace = 'authz_int'::regnamespace
      JOIN pg_rewrite w ON w.ev_class = v.oid)
    SELECT rd.what, fn.oid::regprocedure::text AS fn
    FROM read rd JOIN pg_depend dep ON dep.classid = rd.classid AND dep.objid = rd.objid
    JOIN pg_proc fn ON fn.oid = CASE dep.refclassid
        WHEN 'pg_proc'::regclass THEN dep.refobjid
        WHEN 'pg_operator'::regclass THEN (SELECT o.oprcode FROM pg_operator o WHERE o.oid = dep.refobjid) END
    WHERE fn.pronamespace NOT IN (SELECT n.oid FROM pg_namespace n
                                  WHERE n.nspname IN ('pg_catalog', 'authz', 'authz_gen', 'authz_int'))
      AND fn.provolatile <> 'i'
      AND fn.prolang NOT IN (SELECT l.oid FROM pg_language l WHERE l.lanname IN ('internal', 'c'))
    ORDER BY 1, 2 LIMIT 1
  LOOP
    RAISE EXCEPTION '%: a condition calls %, and nothing in its text shows the call (a function of the row read as a column, a cast, an operator written OPERATOR(...)), so the app role would run it with its own rights, not the policy''s [AZ628]', r.what, r.fn
      USING HINT = 'call it by its name, with parentheses, on the row''s columns, as {app.blocked_doc(this.id)}: rowstile then runs it with the policy''s rights. A function that reads nothing may be marked IMMUTABLE instead';
  END LOOP;
END $ac$;

-- A permission on an object, whether the user may select its row or not: what the functions that act on the
-- object ask (sharing, roles, keys, view_as, break_glass, requests), where authz.can's answer is for rows they may see
CREATE OR REPLACE FUNCTION authz_int.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
<<authz__>>
DECLARE v_integer integer;
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."folders" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR authz_int."folder__edit__has"(o."parent_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."folders" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR authz_int."folder__view__has"(o."parent_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."files" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR authz_int."folder__edit__has"(o."folder_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."files" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR authz_int."folder__edit__has"(o."folder_id")
    OR (NOT coalesce((confidential), false)
    AND authz_int."folder__view__has"(o."folder_id")))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = authz__.v_integer AND (EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist, and on a table with a select rule only rows the user may select: a row they can't see
-- reads as a missing one; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
<<authz__>>
DECLARE v_allowed boolean; v_integer integer;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log), naming who acted as the
    -- audit trail does ('42', 'service:7'; none: nobody signed in). A check answers true or false; one that raises
    -- (a type or a permission the policy doesn't have) is not logged
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(authz_int.actor())::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, v_allowed::text;
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'team' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'folder' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."folders" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR authz_int."folder__edit__has"(o."parent_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."folders" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR authz_int."folder__view__has"(o."parent_id"))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'file' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."files" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR authz_int."folder__edit__has"(o."folder_id"))));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."files" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR authz_int."folder__edit__has"(o."folder_id")
    OR (NOT coalesce((confidential), false)
    AND authz_int."folder__view__has"(o."folder_id")))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'note' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN false; END IF;
      v_integer := p_id::integer;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = authz__.v_integer AND ((coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id")))
    AND (EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")));
        WHEN 'view' THEN RETURN EXISTS (SELECT 1 FROM "app"."notes" o WHERE o."id" = authz__.v_integer AND (EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'folder.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."parent_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE o."id" > $3::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'folder.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."parent_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."folders" o
        WHERE o."id" > $3::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."folder__team" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."parent_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."parent_id")))
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'file.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE o."id" > $3::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id")))
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'file.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id"))
    OR (NOT coalesce((confidential), false)
    AND (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id"))));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id"))
    OR (NOT coalesce((confidential), false)
    AND (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id"))))
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."files" o
        WHERE o."id" > $3::integer AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__viewer" v WHERE v.id = o."id")
    OR (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = o."folder_id"))
    OR (NOT coalesce((confidential), false)
    AND (EXISTS (SELECT 1 FROM authz_int."folder__edit__direct" v WHERE v.id = o."folder_id")
    OR EXISTS (SELECT 1 FROM authz_int."folder__view" v WHERE v.id = o."folder_id"))))
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'note.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE (((coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id")))
    AND (EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE (((coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id")))
    AND (EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")))
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE o."id" > $3::integer AND (((coalesce(o."author_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."file__edit" v WHERE v.id = o."file_id")))
    AND (EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")))
        ORDER BY o."id" LIMIT $4;
      END IF;
    WHEN 'note.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id");
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT $4;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."notes" o
        WHERE o."id" > $3::integer AND EXISTS (SELECT 1 FROM authz_int."file__view" v WHERE v.id = o."file_id")
        ORDER BY o."id" LIMIT $4;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."team__member__why"(p_id integer, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
<<authz__>>
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF $1 IN (SELECT s."team_id" AS id FROM "app"."team_members" s WHERE s."user_id" = (SELECT authz.uid())) THEN
    RETURN NEXT authz__.pad || 'yes  ' || CASE WHEN $4 IS NULL THEN 'member: a row in app.team_members names you' ELSE 'member: a row in app.team_members names them' END || '';
    RETURN;
  END IF;
  FOR v_t IN SELECT e.subj::text AS id FROM (SELECT s."parent_id" AS obj, s."id" AS subj FROM "app"."teams" s WHERE s."id" IS NOT NULL AND s."parent_id" IS NOT NULL) e
             WHERE e.obj = $1 AND EXISTS (SELECT 1 FROM authz_int."team__member" v WHERE v.id = e.subj) LIMIT 1 LOOP
    IF p_asker IS NOT NULL AND NOT authz_int.asker_sees(p_asker, 'team', v_t.id, false) THEN
      RETURN NEXT pad || 'yes  through a team you can''t see';
      RETURN;
    END IF;
    IF NOT ('team:member:' || v_t.id = ANY (p_seen)) THEN
      RETURN NEXT pad || 'yes  through team ' || v_t.id || ', whose member count here too';
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.id::integer, p_depth + 1,
                                 p_seen || ('team:member:' || v_t.id), p_asker);
      RETURN;
    END IF;
  END LOOP;
  RETURN NEXT pad || CASE WHEN $4 IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'team.member';
END $f$;

