CREATE OR REPLACE FUNCTION authz_int."folder__team__why"(p_id integer, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
<<authz__>>
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF $1 IN (SELECT s."folder_id" AS id FROM "app"."folder_teams" s WHERE s."team_id" = ANY ((SELECT authz_int."team__member__ids"())::integer[])) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT s."team_id" AS gid FROM "app"."folder_teams" s WHERE s."folder_id" = $1 AND s."team_id" IN (SELECT id FROM authz_int."team__member")) x LIMIT 1 LOOP
      IF p_asker IS NOT NULL AND NOT authz_int.asker_sees(p_asker, 'team', v_t.gid, false) THEN
        RETURN NEXT pad || 'yes  ' || 'team: a row in app.folder_teams names' || ' a team you can''t see';
        RETURN;
      END IF;
      RETURN NEXT pad || 'yes  ' || 'team: a row in app.folder_teams names' || ' team ' || v_t.gid || CASE WHEN $4 IS NULL THEN ', and you are member there' ELSE ', and they are member there' END;
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.gid::integer, p_depth + 1, p_seen, p_asker);
    END LOOP;
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN $4 IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'folder.team';
END $f$;

CREATE OR REPLACE FUNCTION authz_int."folder__viewer__why"(p_id integer, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
<<authz__>>
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF $1 IN (SELECT g.object_id::integer AS id FROM authz.shares g WHERE g.object_type = 'folder' AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT authz__.pad || 'yes  ' || CASE WHEN $4 IS NULL THEN 'viewer: shared with you' ELSE 'viewer: shared with them' END || CASE WHEN $4 IS NULL OR authz_int.asker_sees($4, 'folder', $1::text, true) THEN coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'folder' AND g.object_id = $1::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '') ELSE '' END;
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN $4 IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'folder.viewer';
END $f$;

CREATE OR REPLACE FUNCTION authz_int."folder__edit__why"(p_id integer, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."folder__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'folder.edit = owner or parent.edit';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."folder__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'owner';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__owner__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT id FROM authz_int."folder__parent__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'parent.edit';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."folder__edit" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."parent_id" AS id FROM "app"."folders" r WHERE r."id" = $1 AND r."parent_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'folder', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'parent is a folder you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'parent is folder '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has edit' ELSE ', without edit' END;
      IF NOT ('folder:edit:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."folder__edit__why"(v_t.id::integer, p_depth + 1 + 1, p_seen || ('folder:edit:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

