CREATE OR REPLACE FUNCTION authz_int."note__edit__why"(p_id integer, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
